<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/purchase_step14.php';if(empty($_SESSION['prc_csrf']))$_SESSION['prc_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['prc_csrf'];$error=null;$success=null;$pending=[];$receipts=[];
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$id=purchase_step14_receive_item($pdo,(int)$_POST['bill_item_id'],(float)$_POST['quantity'],(string)$_POST['receipt_date'],(string)($_POST['batch_code']??''),$_POST['manufacture_date']??null,$_POST['expiry_date']??null,(string)($_POST['delivery_reference']??''),(string)($_POST['notes']??''),isset($_POST['use_as_profit_cost']));$success='Goods Receipt #'.$id.' posted to Inventory.';}$stmt=$pdo->prepare("SELECT i.id bill_item_id,i.purchase_bill_id,i.product_id,i.product_name_snapshot,i.stock_no_snapshot,i.billed_quantity,i.received_quantity,i.unit_cost,(i.billed_quantity-i.received_quantity) remaining,b.invoice_number,b.invoice_date,s.supplier_name FROM purchase_bill_items i JOIN purchase_bills b ON b.id=i.purchase_bill_id AND b.organization_id=i.organization_id JOIN purchase_suppliers s ON s.id=b.supplier_id AND s.organization_id=b.organization_id WHERE i.organization_id=? AND b.status='active' AND i.received_quantity<i.billed_quantity-0.0005 ORDER BY b.invoice_date,i.id");$stmt->execute([$orgId]);$pending=$stmt->fetchAll();$receipts=purchase_step14_receipt_rows($pdo,$orgId);}catch(Throwable $e){$error=$e->getMessage();}
function prc_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function prc_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Receipts - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Goods Receipt / Inventory Inward</small></span></a><div class="os-top-actions"><a class="os-btn" href="purchase_bills.php">Bills</a><a class="os-btn" href="inventory_center.php">Inventory</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a href="purchase_orders.php"><i class="dot"></i>Purchase Orders</a><a href="purchase_bills.php"><i class="dot"></i>Bills / Invoices</a><a class="active" href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a href="purchase_returns.php"><i class="dot"></i>Returns</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 14D • GOODS RECEIPT</div><h1>Receive only what physically arrived, with exact batch and expiry trace.</h1><p>Partial receipt is supported. Posting here creates the purchase inventory movement; expired/lot data then becomes available to STEP 13 FEFO stock control.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'GOODS RECEIPT LIVE':'Review required' ?></span><span class="os-chip"><?= count($pending) ?> pending bill lines</span><span class="os-chip"><?= count($receipts) ?> posted receipts</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Receipt diagnostic:</strong> <?= prc_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Posted:</strong> <?= prc_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Receive Bill Item</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= prc_h($csrf) ?>"><label>Pending Bill Line<select name="bill_item_id" required><option value="">Choose pending line…</option><?php foreach($pending as $p):?><option value="<?= (int)$p['bill_item_id'] ?>"><?= prc_h($p['invoice_number'].' • '.$p['supplier_name'].' • '.$p['stock_no_snapshot'].' • '.$p['product_name_snapshot'].' • Remaining '.$p['remaining']) ?></option><?php endforeach;?></select></label><label>Quantity Received<input type="number" min="0.001" step="0.001" name="quantity" required></label><label>Receipt Date<input type="date" name="receipt_date" value="<?= date('Y-m-d') ?>" required></label><label>Batch / Lot Code<input name="batch_code" placeholder="Blank = safe unbatched code"></label><label>Manufacture Date<input type="date" name="manufacture_date"></label><label>Expiry Date<input type="date" name="expiry_date"></label><label>Delivery / Challan Ref<input name="delivery_reference"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><label><input type="checkbox" name="use_as_profit_cost" value="1"> Use this actual bill unit cost as Product Profit Basis</label><button>Post Goods Receipt →</button></form><div class="pp-alert" style="margin-top:12px"><strong>Cost rule:</strong> the checkbox is explicit. Without it, receipt stock still carries its unit cost for inventory valuation, but Product Sale profit basis is not changed.</div></article><article class="os-card pp-span-7"><h2>Pending Receipt Lines</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Invoice</th><th>Supplier</th><th>Product</th><th>Billed</th><th>Received</th><th>Remaining</th><th>Unit Cost</th></tr></thead><tbody><?php foreach($pending as $p):?><tr><td><?= prc_h($p['invoice_number']) ?></td><td><?= prc_h($p['supplier_name']) ?></td><td><b><?= prc_h($p['stock_no_snapshot']) ?></b><small><?= prc_h($p['product_name_snapshot']) ?></small></td><td><?= prc_h($p['billed_quantity']) ?></td><td><?= prc_h($p['received_quantity']) ?></td><td><b><?= prc_h($p['remaining']) ?></b></td><td><?= prc_m($p['unit_cost']) ?></td></tr><?php endforeach;?><?php if(!$pending):?><tr><td colspan="7">No pending bill receipt lines.</td></tr><?php endif;?></tbody></table></div><h2 style="margin-top:18px">Posted Receipts</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>GRN</th><th>Supplier</th><th>Invoice</th><th>Qty</th><th>Delivery Ref</th></tr></thead><tbody><?php foreach($receipts as $r):?><tr><td><?= prc_h($r['receipt_date']) ?></td><td><b><?= prc_h($r['receipt_number']) ?></b></td><td><?= prc_h($r['supplier_name']) ?></td><td><?= prc_h($r['invoice_number']) ?></td><td><?= prc_h($r['total_qty']) ?></td><td><?= prc_h($r['delivery_reference']?:'—') ?></td></tr><?php endforeach;?><?php if(!$receipts):?><tr><td colspan="6">No goods receipts yet.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>Receipt rule:</strong> inventory increases only here (or in the independent STEP 13 Opening Stock workflow). Bill entry alone never changes stock.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
